mapper.sql:
WHERE f20.`run_id` = #{runId}
  AND f20.`horizon_days` = 20

    AND (f20.`code` LIKE CONCAT('%', #{keyword}, '%') OR i.`name` LIKE CONCAT('%', #{keyword}, '%'))


    AND f20.`target15_probability` >= #{minProbability}

mapper.select:
SELECT DISTINCT `trade_date`
FROM `stock_daily_all`
WHERE `adjustflag` = #{adjustFlag}
ORDER BY `trade_date` DESC
LIMIT #{limit}
